<section class="panel"><header class="panel-head"><div><span class="eyebrow">Data ownership</span><h2>Authority and override policies</h2></div><span class="panel-meta"><?= count($authorities) ?> policies</span></header><div class="table-wrap"><table><thead><tr><th>Entity</th><th>Domain</th><th>Authority</th><th>Mode</th><th>Override</th></tr></thead><tbody><?php foreach($authorities as$a): ?><tr><td><?= h(entity_system_find($entities,(int)$a['entity_id'])['entity_name']??'Unknown') ?></td><td><?= h(status_label($a['domain_code'])) ?></td><td><?= h(entity_system_find($entities,(int)$a['authority_entity_id'])['entity_name']??'Unknown') ?></td><td><?= h(status_label($a['authority_mode'])) ?></td><td><?= h(status_label($a['override_policy'])) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<div class="entity-split"><section class="panel"><header class="panel-head"><div><span class="eyebrow">Access migration</span><h2>Entity access scopes</h2></div><span class="panel-meta"><?= count($scopes) ?> scopes</span></header><div class="record-list"><?php foreach(array_slice($scopes,0,20)as$s): ?><article class="record-card"><strong><?= h(data_user_name($s['user_id'])) ?></strong><small><?= h(entity_system_find($entities,(int)$s['entity_id'])['entity_name']??'Unknown') ?> · <?= h(status_label($s['scope_type'])) ?> · <?= h($s['module_code']) ?></small></article><?php endforeach; ?></div></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Authority policy</span><h2>Add domain owner</h2></div></header><?php if(can('companies.administer')): ?><form class="compact-form" action="<?= h(app_url('entity-system-action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_authority"><input type="hidden" name="return_tab" value="authorities"><label><span>Applies to</span><select name="entity_id"><?php foreach($entities as$e): ?><option value="<?= (int)$e['id'] ?>"><?= h($e['entity_name']) ?></option><?php endforeach; ?></select></label><label><span>Authority entity</span><select name="authority_entity_id"><?php foreach($entities as$e): ?><option value="<?= (int)$e['id'] ?>"><?= h($e['entity_name']) ?></option><?php endforeach; ?></select></label><label><span>Domain</span><input name="domain_code" value="supplier_master" required></label><label><span>Mode</span><select name="authority_mode"><option value="authoritative">Authoritative</option><option value="internal_governed">Internal governed</option><option value="external_governed">External governed</option><option value="bidirectional">Bidirectional</option></select></label><label><span>Override policy</span><select name="override_policy"><option value="governed_override">Governed override</option><option value="local_only">Local only</option><option value="no_override">No override</option></select></label><label><span>Effective</span><input type="date" name="effective_from" value="<?= date('Y-m-d') ?>"></label><label class="span-2"><span>Evidence</span><textarea name="evidence_note" required></textarea></label><div class="span-2"><button class="button primary">Save Authority</button></div></form><?php endif; ?></section></div>
